+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+const successMessage = document.getElementById('successMessage');
+
+const patterns = {
+    phone: /^(?:\+?1[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}$|^$/
+};
+
+function showError(input, message) {
+    const errorElement = document.getElementById(`${input.id}-error`);
+    if (message) {
+        errorElement.textContent = message;
+        errorElement.classList.add('show');
+        input.setAttribute('aria-invalid', 'true');
+    } else {
+        errorElement.textContent = '';
+        errorElement.classList.remove('show');
+        input.setAttribute('aria-invalid', 'false');
+    }
+}
+
+function validateFullName(value) {
+    if (!value.trim()) {
+        return 'Full name is required.';
+    }
+    if (value.trim().length < 2) {
+        return 'Full name must be at least 2 characters.';
+    }
+    return '';
+}
+
+function validateEmail(value) {
+    if (!value.trim()) {
+        return 'Email address is required.';
+    }
+    const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+    if (!emailPattern.test(value)) {
+        return 'Please enter a valid email address.';
+    }
+    return '';
+}
+
+function validatePhone(value) {
+    if (!value.trim()) {
+        return '';
+    }
+    if (!patterns.phone.test(value)) {
+        return 'Please enter a valid phone number. Format: (123) 456-7890 or +1 (123) 456-7890';
+    }
+    return '';
+}
+
+function validateForm() {
+    const fullNameError = validateFullName(fullNameInput.value);
+    const emailError = validateEmail(emailInput.value);
+    const phoneError = validatePhone(phoneInput.value);
+
+    showError(fullNameInput, fullNameError);
+    showError(emailInput, emailError);
+    showError(phoneInput, phoneError);
+
+    return !fullNameError && !emailError && !phoneError;
+}
+
+fullNameInput.addEventListener('blur', () => {
+    showError(fullNameInput, validateFullName(fullNameInput.value));
+});
+
+fullNameInput.addEventListener('input', () => {
+    if (fullNameInput.getAttribute('aria-invalid') === 'true') {
+        showError(fullNameInput, validateFullName(fullNameInput.value));
+    }
+});
+
+emailInput.addEventListener('blur', () => {
+    showError(emailInput, validateEmail(emailInput.value));
+});
+
+emailInput.addEventListener('input', () => {
+    if (emailInput.getAttribute('aria-invalid') === 'true') {
+        showError(emailInput, validateEmail(emailInput.value));
+    }
+});
+
+phoneInput.addEventListener('blur', () => {
+    showError(phoneInput, validatePhone(phoneInput.value));
+});
+
+phoneInput.addEventListener('input', () => {
+    if (phoneInput.getAttribute('aria-invalid') === 'true') {
+        showError(phoneInput, validatePhone(phoneInput.value));
+    }
+});
